"""Original advanced ODE candidates, with explicit finite parameter domains.
Executed residual, algebraic and finite-integral checks are separate from the
analytic obligations in each solution. No assertion of human review is made.
"""
from common import *
t,z=s.symbols('t z',real=True)
reg=Registry('differential equations');register=reg.register
catalog=reg.catalog;build=reg.build;verify=reg.verify;all_candidates=reg.all_candidates

@register('rotating-instability','rotating-frame-stability','A time-periodic symmetric field can be stabilized by rotation; recover the constant generator and its spectral growth, including the effect of a full return.','Unlike scalar periodic logistic multipliers, this requires a noncommuting matrix coordinate change; integrating instantaneous eigenvalues gives a wrong result.',[{'a':a,'w':w} for a,w in [(3,1),(4,1),(4,2),(5,1),(5,2),(5,3),(6,2),(6,3),(7,3),(7,4)]],'rotating-frame-Floquet-reduction',('matrix exponentials','spectral radius'))
def rotating(a,w):
 J=s.Matrix([[0,-1],[1,0]]);D=s.diag(a,-a);B=D-w*J;period=s.pi/w;answer=s.exp(period*s.sqrt(a*a-w*w))
 return item(T('Let the real vector solve ')+r'X\prime=A(t)X,\quad A(t)=R('+L(w)+r't)\begin{pmatrix}'+L(a)+r'&0\\0&-'+L(a)+r'\end{pmatrix}R('+L(w)+r't)^{-1},\quad R(\theta)=\begin{pmatrix}\cos\theta&-\sin\theta\\\sin\theta&\cos\theta\end{pmatrix}.'+T('Let M carry initial data at zero to time ')+L(period)+T('. Find the spectral radius of M, the largest modulus of its eigenvalues.'),answer,[(s.exp(period*a),'integrate the positive instantaneous eigenvalue'),(s.exp(period*s.sqrt(a*a+w*w)),'give the rotating-frame term a symmetric sign'),(s.exp(-period*s.sqrt(a*a-w*w)),'select the contracting multiplier'),(s.exp(2*period*s.sqrt(a*a-w*w)),'use two periods'),(s.exp(period*s.sqrt(a*a-w*w)/2),'use half the period')],[T('Set ')+r'X(t)=R('+L(w)+r't)Z(t).'+T(' Differentiating the rotating coordinates gives ')+r'Z\prime=BZ,\quad B='+L(B)+'.',r'B^2='+L(a*a-w*w)+r'I_2,qquad R('+L(w*period)+r')=-I_2.',T('Thus the return matrix is ')+r'M=-e^{'+L(period)+r' B}'+T(', with eigenvalues ')+r'-e^{\pm '+L(period*s.sqrt(a*a-w*w))+r'}.'],[check('constant generator squared',B*B,(a*a-w*w)*s.eye(2)),check('characteristic polynomial',(z*s.eye(2)-B).det(),z*z-(a*a-w*w)),truth('real distinct generator exponents',bool(a>w>0))],['Real two-component solutions; a>w>0 in every finite instance; I_2 is the two-by-two identity matrix.'],['The rotation is a smooth invertible coordinate map. The constant generator has distinct real eigenvalues, so exponentiating it gives both multipliers. Multiplication by -I_2 affects signs but not moduli.'],'time-periodic-rotating-indefinite-matrix')

@register('weighted-string-first-eigenvalue','Liouville-gauge-spectral-boundary','A change of independent variable alone leaves a first derivative; a dependent-variable gauge must remove it before boundary quantization and a lower-bound proof.','Different from a dependent-power nonlinear IVP and from a third-order Schwarzian IVP: this is a weighted spectral boundary problem.',[{'n':n,'k':k} for n,k in [(3,1),(4,1),(5,1),(6,1),(7,1),(4,2),(5,2),(6,2),(7,2),(8,2)]],'Liouville-coordinate-and-gauge',('integration by parts','Dirichlet eigenvalues'))
def weighted_string(n,k):
 # Interval endpoints have an explicit angular length, but neither gauge nor
 # transformed operator is disclosed in the question.
 alpha=s.pi/(2*n);left=0 if k==1 else -s.tan(alpha);right=s.tan(alpha);length=alpha if k==1 else 2*alpha
 freq=s.pi/length;answer=freq**2-1
 u=s.Function('u')(z);v=s.sec(z)*u;d=lambda f:s.cos(z)**2*s.diff(f,z)
 identity=s.simplify(d(d(v))-s.cos(z)**3*(s.diff(u,z,2)+u))
 return item(r'y\prime\prime+\frac{\lambda}{(1+t^2)^2}y=0,\quad y('+L(left)+r')=y('+L(right)+r')=0.'+T('Find the least real lambda for which a nonzero real twice continuously differentiable solution exists.'),answer,[(freq**2,'omit the gauge potential'),(freq**2+1,'reverse the gauge correction'),((freq/2)**2-1,'double the transformed interval'),((2*freq)**2-1,'halve the transformed interval'),((freq-1)**2,'shift the frequency instead of its square')],[T('Use the angular coordinate and gauge ')+r'z=\arctan t,qquad y(t)=\sec z\,u(z).',r'\frac{\mathrm d^2y}{\mathrm dt^2}=\cos^3z\,(u\prime\prime+u),qquad u\prime\prime+(\lambda+1)u=0.',T('The transformed interval has length ')+L(length)+T(', and its endpoint values are zero. Integrating against u gives ')+r'(\lambda+1)\int u^2\,\mathrm dz=\int (u\prime)^2\,\mathrm dz.',T('The first Dirichlet frequency on this interval is ')+L(freq)+T('; solving the constant-coefficient equation shows that lower positive frequencies cannot have two endpoint zeros. A sine at this frequency attains the value.')],[check('gauge transformed second derivative',identity),check('first sine residual',s.diff(s.sin(freq*z),z,2)+freq**2*s.sin(freq*z)),check('first eigenvalue relation',answer+1,freq**2),truth('coordinate interval avoids tangent poles',bool(0<alpha<s.pi/2))],['Real classical solutions on the closed finite interval. The coordinate lies strictly between minus and plus pi/2, so the gauge never vanishes.'],['For lambda+1<=0, integration by parts forces the zero solution. For positive lambda+1, the constant-coefficient general solution and two zero endpoints require sqrt(lambda+1) times the interval length to be a positive integer multiple of pi. The first such integer is one.'],'weighted-Sturm-Liouville-arctangent-gauge')

@register('homoclinic-mass','homoclinic-energy-separatrix','Use decay at both infinities to select the zero energy orbit, prove the positive profile and its unique turning amplitude, then integrate its fourth-power mass.','A nonlinear period is a closed positive-energy orbit; this orbit is nonperiodic and selected by two asymptotic boundary conditions.',[{'a':a,'b':b} for a,b in [(1,2),(1,3),(2,2),(2,3),(2,5),(3,2),(3,4),(3,5),(4,3),(4,5)]],'zero-energy-homoclinic-orbit',('energy invariants','improper integrals'))
def homoclinic(a,b):
 f=s.sqrt(2/b)*a/s.cosh(a*t);answer=16*a**3/(3*b*b)
 U,V=s.symbols('U V',real=True);energy=V*V/2-a*a*U*U/2+b*U**4/4
 return item(r'y\prime\prime='+L(a*a)+r'y-'+L(b)+r'y^3,\quad y(t)>0,\quad y\prime(0)=0,\quad\lim_{t\to\pm\infty}(y(t),y\prime(t))=(0,0).'+T('For this nonzero real solution find ')+r'\int_{-\infty}^{\infty}y(t)^4\,\mathrm dt.',answer,[(8*a**3/(3*b*b),'count only one side of the turning point'),(32*a**3/(3*b*b),'double the orbit integral'),(4*a/(3*b),'integrate a squared amplitude in place of the fourth power'),(16*a**4/(3*b*b),'omit the time-scale Jacobian'),(16*a**2/(3*b*b),'divide by the time scale twice'),(4*a/b,'compute the second-power mass'),(4*a**3/(3*b*b),'omit the factor two in the turning amplitude squared')],[T('The conserved energy is ')+r'E=\frac{(y\prime)^2}{2}-\frac{'+L(a*a)+r'y^2}{2}+\frac{'+L(b)+r'y^4}{4}.'+T('The decay conditions force E to be zero.'),r'y(0)=\sqrt{\frac{'+L(2*a*a)+r'}{'+L(b)+r'}},\qquad y(t)=\sqrt{\frac{'+L(2*a*a)+r'}{'+L(b)+r'}}\operatorname{sech}('+L(a)+r't).',T('The profile satisfies the equation and the turning data, so uniqueness identifies it. With ')+r'v=\tanh('+L(a)+r't),',r'\int_{-\infty}^{\infty}\operatorname{sech}^4('+L(a)+r't)\,\mathrm dt=\frac1{'+L(a)+r'}\int_{-1}^1(1-v^2)\,\mathrm dv=\frac4{'+L(3*a)+r'}.'],[check('energy conserved',s.diff(energy,U)*V+s.diff(energy,V)*(a*a*U-b*U**3)),check('profile nonlinear residual',s.diff(f,t,2)-a*a*f+b*f**3),check('turning slope',s.diff(f,t).subs(t,0)),check('exact fourth-power integral',((2*a*a/b)**2/a)*s.integrate(1-z*z,(z,-1,1)),answer)],['Real classical solution; sech t means 1/cosh t. Both the function and derivative have the stated limits.'],['Decay makes the conserved energy zero. At the positive turning point, zero energy uniquely fixes its height. The polynomial vector field gives uniqueness for these two initial data. The displayed global positive profile meets both decay conditions and its fourth power is integrable.'],'positive-homoclinic-zero-energy-fourth-mass')

@register('critical-radial-bubble','critical-Lane-Emden-singular-origin','The radial ODE is singular at the initial point; identify a globally positive bubble and justify uniqueness through the integrated radial equation before evaluating a global mass.','Unlike a regular IVP residual check, uniqueness at the coefficient singularity requires a Volterra integral argument; critical dimension fixes the mass scaling.',[{'n':n,'a':a} for n,a in [(3,1),(3,2),(4,1),(4,2),(5,1),(5,2),(6,1),(6,2),(7,1),(8,1)]],'singular-radial-Volterra-and-critical-scaling',('radial equations','beta integral'))
def bubble(n,a):
 r=s.symbols('r',positive=True);q=(n-2)/2;f=(a/(1+a*a*r*r))**q;power=2*n/(n-2)
 answer=s.gamma(n/2)**2/(2*s.gamma(n));res=s.diff(f,r,2)+(n-1)*s.diff(f,r)/r+n*(n-2)*f**((n+2)/(n-2))
 # Rationalize the fractional powers using positivity, then verify by direct
 # differentiation independently of the beta-integral value.
 res=s.powdenest(res,force=True)
 return item(r'y\prime\prime+\frac{'+L(n-1)+r'}r y\prime+'+L(n*(n-2))+r'y^{'+L((n+2)/(n-2))+r'}=0\quad(r>0),\quad y(0)='+L(a**q)+r',\quad y\prime(0)=0.'+T('Take the positive solution that is twice continuously differentiable at the origin. Find ')+r'\int_0^\infty r^{'+L(n-1)+r'}y(r)^{'+L(power)+r'}\,\mathrm dr.'+T('Here ')+r'\Gamma(v)=\int_0^\infty x^{v-1}e^{-x}\,\mathrm dx\quad(v>0).',answer,[(a**n*answer,'omit the radial scaling Jacobian'),(2*answer,'omit the square-radius Jacobian'),(answer/2,'apply that Jacobian twice'),(s.gamma(n/2)**2/s.gamma(n+1),'shift the beta total parameter'),(s.gamma((n-1)/2)**2/(2*s.gamma(n-1)),'drop one radial dimension')],[T('Multiplying by the radial density and integrating from the regular origin yields ')+r'r^{'+L(n-1)+r'}y\prime(r)=-'+L(n*(n-2))+r'\int_0^r v^{'+L(n-1)+r'}y(v)^{'+L((n+2)/(n-2))+r'}\,\mathrm dv.',T('Direct differentiation gives the positive solution ')+r'y(r)=\left(\frac{'+L(a)+r'}{1+'+L(a*a)+r'r^2}\right)^{'+L(q)+r'}.',T('Set ')+r'u='+L(a*a)+r'r^2.'+T('The powers of the scale cancel, leaving ')+r'\frac12\int_0^\infty\frac{u^{'+L(n/2-1)+r'}}{(1+u)^{'+L(n)+r'}}\,\mathrm du=\frac{\Gamma('+L(n/2)+r')^2}{2\Gamma('+L(n)+r')}.'],[check('bubble original radial ODE',res),check('regular origin value',f.subs(r,0),a**q),check('regular origin slope',s.limit(s.diff(f,r),r,0),0),check('critical scale cancellation',n-q*power,0),check('beta normalization',s.expand_func(s.beta(n/2,n/2))/2,answer)],['Integer dimension at least three; positive real powers; the solution is positive and regular at the origin.'],['The integrated radial equation becomes a Volterra equation after one further integration. On a short interval where two positive solutions remain in a compact positive range, the nonlinearity is Lipschitz and the difference is bounded by a constant times r squared times its supremum; a sufficiently short interval forces equality. Continue by ordinary uniqueness away from the origin. The verified positive global bubble therefore is the specified solution. The transformed beta parameters are positive, proving convergence at both endpoints.'],'critical-radial-bubble-scale-invariant-mass')

@register('isochronous-shear','isochronous-potential-even-shear','An even shear of the coordinate changes the potential but cancels out of the period quadrature; show that the singular turning endpoints are integrable and the full orbit closes.','Not a nonlinear oscillator beta substitution: the decisive step is cancellation of the odd Jacobian term over an asymmetric physical orbit.',[{'c':str(c),'h':h} for c,h in [(R(1,3),1),(R(1,3),2),(R(1,2),1),(R(1,2),3),(R(2,3),2),(R(2,3),3),(R(-1,3),1),(R(-1,3),3),(R(-1,2),2),(R(-2,3),2)]],'energy-period-shear-cancellation',('energy quadrature','inverse functions'))
def shear(c,h):
 u=s.symbols('u',real=True);g=u+c*(s.sqrt(1+u*u)-1);answer=2*s.pi
 inv=((t+c)-c*s.sqrt((t+c)**2+1-c*c))/(1-c*c)
 return item(T('Define the real function ')+r' U(x)=\frac{x+'+L(c)+r'-('+L(c)+r')\sqrt{(x+'+L(c)+r')^2+'+L(1-c*c)+r'}}{'+L(1-c*c)+r'}.'+T('The solution obeys ')+r'x\prime\prime+U(x)U\prime(x)=0,\quad x(0)='+L(g.subs(u,h))+r',\quad x\prime(0)=0.'+T('Find its least positive period. The prime on U differentiates its argument; primes on x differentiate time.'),answer,[(s.pi,'count only one traversal between turning points'),(4*s.pi,'count the complete orbit twice'),(2*s.pi*s.sqrt(1-c*c),'treat the shear as a constant scale'),(2*s.pi/(1-c*c),'keep only the inverse formula denominator'),(2*s.pi*s.sqrt(1+h*h),'freeze the nonlinear Jacobian at a turning point')],[T('The inverse coordinate of U is ')+r'x=g(u)=u+('+L(c)+r')(\sqrt{1+u^2}-1),\quad g\prime(u)=1+('+L(c)+r')\frac{u}{\sqrt{1+u^2}}>0.',T('Conservation gives ')+r'\frac{(x\prime)^2}{2}+\frac{U(x)^2}{2}=\frac{'+L(h*h)+r'}2.'+T('The turning coordinates are ')+r'u=\pm '+L(h)+'.',r'P=2\int_{-'+L(h)+r'}^{'+L(h)+r'}\frac{g\prime(u)}{\sqrt{'+L(h*h)+r'-u^2}}\,\mathrm du.',T('The shear contribution is odd and integrates to zero. The remaining integral is pi, so the two traversals give the stated period.')],[check('inverse relation algebra before square root',((g+c)-u)**2,c*c*(1+u*u)),check('Jacobian odd component',s.diff(g,u)+s.diff(g,u).subs(u,-u),2),check('coordinate at origin',g.subs(u,0),0),truth('global monotonic coordinate bound',bool(abs(c)<1))],['All real coordinates; the square root is principal. The finite domains have nonzero shear magnitude less than one and positive turning coordinate.'],['Because |c|<1, the derivative of g is bounded below by 1-|c| and g maps the real line bijectively onto itself. Solving the quadratic relation with this monotone branch gives U. The potential is proper and smooth. The energy orbit is confined between the two finite turning points, with nonzero velocity inside. Turning singularities in the quadrature are inverse square roots and integrable; uniqueness and reflection in time complete the orbit, with no earlier state return.'],'even-coordinate-shear-full-period-cancellation')

@register('polynomial-root-moment','polynomial-ODE-root-moment','A differential equation fixes the leading polynomial coefficients, which control a root moment through Newton identities without locating any roots.','Unlike a direct high derivative, the requested quantity is a symmetric function of unknown roots and must be recovered from the ODE recurrence.',[{'n':n,'a':a} for n,a in [(4,1),(5,1),(6,1),(7,1),(8,1),(4,2),(5,2),(6,2),(7,2),(8,2)]],'polynomial-ODE-coefficients-and-Newton-sums',('polynomial coefficient comparison','Newton identities'))
def roots(n,a):
 # Monic rescaled Hermite polynomial, constructed independently by recurrence.
 x=s.symbols('x');p0=s.Integer(1);p1=x
 for j in range(1,int(n)):p0,p1=p1,s.expand(x*p1-R(j,2)/a*p0)
 poly=p1;answer=n*(n-1)*(2*n-3)/(4*a*a)
 c2=-n*(n-1)/(4*a);c4=n*(n-1)*(n-2)*(n-3)/(32*a*a)
 return item(T('A monic polynomial p of degree ')+L(n)+T(' satisfies ')+r'p\prime\prime(x)-'+L(2*a)+r'x p\prime(x)+'+L(2*a*n)+r'p(x)=0.'+T('Let its complex roots, counted with multiplicity, be ')+r'r_1,\ldots,r_{'+L(n)+r'}.'+T('Find ')+r'\sum_{j=1}^{'+L(n)+r'}r_j^4.',answer,[(n*(n-1)/(2*a),'return the second root moment'),(n*n*(n-1)**2/(8*a*a),'discard the fourth coefficient in the Newton identity'),(n*(n-1)*(2*n-1)/(4*a*a),'shift the coefficient recurrence'),(n*(n-1)*(2*n-3)/(2*a*a),'double the Newton sum'),(n*(n-1)*(2*n-3)/(8*a*a),'halve the Newton sum')],[T('Write the leading terms as ')+r'p(x)=x^{'+L(n)+r'}+c_2x^{'+L(n-2)+r'}+c_4x^{'+L(n-4)+r'}+\cdots.'+T('Coefficient comparison makes all coefficients of opposite parity vanish and gives ')+r'c_2='+L(c2)+r',\quad c_4='+L(c4)+'.',T('Define the power sums ')+r'S_k=\sum_jr_j^k.'+T('Newton identities give ')+r'S_2=-2c_2,\qquad S_4+c_2S_2+4c_4=0.',r'S_4=2c_2^2-4c_4.'],[check('independently built polynomial ODE',s.diff(poly,x,2)-2*a*x*s.diff(poly,x)+2*a*n*poly),check('second leading coefficient',poly.coeff(x,int(n)-2),c2),check('fourth leading coefficient',poly.coeff(x,int(n)-4),c4),check('Newton fourth sum',2*c2*c2-4*c4,answer)],['Roots are complex and counted with algebraic multiplicity; their fourth-power sum is real. Monic means leading coefficient one.'],['The coefficient recurrence descends by two, uniquely determining every coefficient and proving existence through the displayed finite polynomial recurrence. Newton identities are algebraic and do not require distinct or real roots.'],'unknown-polynomial-ODE-to-root-fourth-moment')

@register('nonnormal-transient-maximum','nonnormal-flow-transient-growth','Negative eigenvalues do not exclude finite-time amplification; optimize the largest singular value of the full flow over time and initial direction.','Distinct from Floquet growth: the system is autonomous and asymptotically stable, while the requested quantity is its finite-time operator-norm maximum.',[{'k':str(k)} for k in [R(5,2),3,R(7,2),4,5,6,7,8,9,10]],'matrix-exponential-singular-value-optimization',('singular values','matrix exponentials'))
def transient(k):
 d=s.sqrt(k*k-4);tau=d/k;answer=s.exp(-tau)*(k+d)/2
 M=s.Matrix([[1,k*t],[0,1]]);G=M.T*M;lam=((s.sqrt(4+k*k*t*t)+k*t)/2)**2
 return item(r'X\prime=\begin{pmatrix}-1&'+L(k)+r'\\0&-1\end{pmatrix}X.'+T('Using the Euclidean norm, find ')+r'\sup_{t\ge0,\ X(0)\ne0}\frac{\|X(t)\|_2}{\|X(0)\|_2}.',answer,[(s.Integer(1),'infer monotone decay from the eigenvalues'),(s.exp(-tau)*(k+d),'omit the singular-value factor one half'),(s.exp(-tau)*(k-d)/2,'choose the smaller singular value'),(s.exp(-d)*(k+d)/2,'omit the rate divisor in the maximizing time'),((k+d)/2,'omit the exponential damping')],[T('The exact flow is ')+r'e^{-t}\begin{pmatrix}1&'+L(k)+r't\\0&1\end{pmatrix}.'+T('Its largest singular value is ')+r'g(t)=e^{-t}\frac{\sqrt{4+'+L(k*k)+r't^2}+'+L(k)+r't}{2}.',r'\frac{\mathrm d}{\mathrm dt}\ln g(t)=-1+\frac{'+L(k)+r'}{\sqrt{4+'+L(k*k)+r't^2}}.',T('This derivative decreases strictly from a positive value to minus one, so its unique zero ')+r't_*='+L(tau)+T(' is the global maximum. A right singular vector attains the norm for that time.')],[check('flow Gram characteristic root',(G-lam*s.eye(2)).det()),check('log singular-value derivative',s.diff(s.asinh(k*t/2)-t,t),-1+k/s.sqrt(4+k*k*t*t)),check('maximizing condition',4+k*k*tau*tau,k*k),truth('strict transient amplification regime',bool(k>2))],['Real two-component initial vectors; t>=0; Euclidean norm.'],['The flow follows by exponentiating a nilpotent Jordan part. The Gram matrix is symmetric positive definite; its determinant is one and its larger eigenvalue is the verified square. The logarithmic derivative gives a unique interior maximum and the flow tends to zero as time tends to infinity. The maximum over initial directions equals the largest singular value.'],'stable-Jordan-flow-global-transient-norm')

@register('spectral-potential-derivative','simple-eigenvalue-Hellmann-Feynman','Differentiate a boundary eigenvalue problem, eliminate the unknown eigenfunction derivative by Green identity, and normalize an oscillatory moment.','Unlike boundary compatibility at resonance, this computes sensitivity of a simple spectral branch to a distributed potential.',[{'n':n,'ell':str(ell)} for n,ell in [(1,1),(2,1),(3,1),(4,1),(5,1),(1,2),(2,2),(3,2),(1,R(1,2)),(2,R(1,2))]],'eigenvalue-variation-and-adjoint-cancellation',('simple Dirichlet eigenvalues','integration by parts'))
def spectral(n,ell):
 f=s.sin(n*s.pi*t/ell);norm=ell/2;moment=ell**3*(R(1,6)-1/(4*n*n*s.pi**2));answer=moment/norm
 return item(r'-y\prime\prime+\varepsilon t^2y=\lambda(\varepsilon)y,\quad y(0)=y('+L(ell)+r')=0.'+T('Let the eigenvalue branch satisfy ')+r'\lambda(0)='+L((n*s.pi/ell)**2)+T('. Find ')+r'\lambda\prime(0).',answer,[(ell*ell/3,'replace the oscillatory weight by its mean before integrating'),(ell*ell*(R(1,3)+1/(2*n*n*s.pi**2)),'reverse the oscillatory correction'),(-answer,'reverse the perturbing potential sign'),(moment,'omit the eigenfunction normalization'),(ell*ell*(R(1,3)-1/(n*n*s.pi**2)),'double the oscillatory correction')],[T('At zero perturbation choose ')+r'y_0(t)=\sin('+L(n*s.pi/ell)+r' t).'+T('Differentiate the equation with respect to the parameter and multiply by the unperturbed eigenfunction.'),T('The terms involving the eigenfunction derivative cancel after two integrations by parts: both it and the eigenfunction vanish at the endpoints. Hence ')+r'\lambda\prime(0)=\frac{\int_0^{'+L(ell)+r'}t^2\sin^2('+L(n*s.pi/ell)+r' t)\,\mathrm dt}{\int_0^{'+L(ell)+r'}\sin^2('+L(n*s.pi/ell)+r' t)\,\mathrm dt}.',r'\int_0^{'+L(ell)+r'}\sin^2('+L(n*s.pi/ell)+r' t)\,\mathrm dt='+L(norm)+r',\quad \int_0^{'+L(ell)+r'}t^2\sin^2('+L(n*s.pi/ell)+r' t)\,\mathrm dt='+L(moment)+'.'],[check('unperturbed ODE residual',-s.diff(f,t,2),(n*s.pi/ell)**2*f),check('normalization integral',s.integrate(f*f,(t,0,ell)),norm),check('weighted perturbation integral',s.integrate(t*t*f*f,(t,0,ell)),moment)],['The interval length is positive and the spectral index is a positive integer. The eigenvalue branch through the displayed simple Dirichlet eigenvalue is differentiable near zero.'],['Regular self-adjoint Dirichlet eigenvalues in one dimension are simple; smooth bounded potential perturbations have differentiable local eigenpairs. This standard perturbation theorem is an analytic prerequisite, not a machine-proved claim. Differentiated boundary values are zero. Green identity then removes the unknown derivative and the executed elementary integrals evaluate the remaining ratio.'],'Dirichlet-eigenvalue-first-potential-variation')

_osgood_domains=[]
for j in range(10):
 good=[(0,3),(1,1),(1,0),(-1,4),(1,-1)][j%5]
 bad=[(2,0),(1,2),(1,3),(3,-2),(2,-4)]
 tests=[bad[(j+k)%5] for k in range(3)];tests.insert(j%4,good)
 _osgood_domains.append({'tests':tests})
@register('logarithmic-uniqueness-borderline','Osgood-integral-uniqueness','Continuity with zero vector field at the initial point does not determine uniqueness; distinguish a double-logarithmic borderline by inverting the escape-time integral.','Not a separable initial-value evaluation: the issue is whether separation is legitimate through the zero equilibrium, and finite escape time creates waiting-time branches.',_osgood_domains,'Osgood-divergence-and-waiting-time-branches',('improper integrals','local uniqueness'))
def osgood(tests):
 good=lambda a,b:a<1 or (a==1 and b<=1)
 selected=[j+1 for j,(a,b) in enumerate(tests) if good(a,b)];assert len(selected)==1;answer=s.Integer(selected[0])
 rows=r'\begin{array}{c|cc}j&\alpha_j&\beta_j\\'+r'\\'.join(str(j+1)+'&'+L(a)+'&'+L(b) for j,(a,b) in enumerate(tests))+r'\end{array}'
 u=s.symbols('u',positive=True)
 return item(T('For each row, consider nonnegative solutions near time zero of ')+r'y\prime=f_j(y),\quad y(0)=0,\qquad f_j(0)=0,\quad f_j(y)=y\bigl(\ln(1/y)\bigr)^{\alpha_j}\bigl(\ln\ln(1/y)\bigr)^{\beta_j}\quad(0<y<e^{-e}).'+rows+T('For which index is the zero solution the unique nonnegative local solution?'),answer,[(s.Integer(j+1),'misclassify the logarithmic escape integral for row '+str(j+1)) for j in range(4) if j+1!=answer],[T('A nonzero branch can leave zero precisely when its escape-time integral is finite. Substitution ')+r'u=\ln(1/y)'+T(' changes that integral to ')+r'\int^{\infty}\frac{\mathrm du}{u^{\alpha_j}(\ln u)^{\beta_j}}.',T('This diverges when ')+r'\alpha_j<1\quad\textnormal{or}\quad\alpha_j=1,\ \beta_j\le1.'+T('It converges in the complementary cases.'),T('For a convergent integral, invert the strictly increasing escape-time function and optionally delay departure from zero. For a divergent integral, a positive branch cannot be reached in finite time. Only the displayed answer row has divergence.')],[check('logarithmic escape Jacobian',s.diff(s.exp(-u),u)/s.exp(-u),-1),truth('exactly one divergent finite-domain case',len(selected)==1),* [truth('row '+str(j+1)+' exponent classification',bool(good(a,b))==bool(j+1==answer)) for j,(a,b) in enumerate(tests)]],['Only nonnegative forward local solutions with values below e^{-e} are considered. Each vector field is continuous at zero and strictly positive for positive y.'],['The logarithm powers are positive real powers on the stated domain. The standard logarithmic integral test follows from comparison with powers when alpha differs from one; at alpha one use v=ln u and the power test. If the escape integral is finite, its inverse has derivative f(y) tending to zero at the origin, so joining it to a zero waiting interval gives a classical C1 solution. If it diverges, integrating any hypothetical positive branch backward to its first departure time gives an infinite elapsed time, a contradiction.'],'zero-equilibrium-double-log-uniqueness-test')

@register('global-Riccati-threshold','Riccati-barrier-global-versus-escape','A polynomial comparison solution separates global trajectories from finite-time blowup; prove both directions with barriers rather than merely testing a candidate.','Unlike the legacy known-particular Riccati IVP, the question quantifies over a forcing parameter and asks for a sharp global-existence threshold.',[{'n':n,'k':k} for n,k in [(2,1),(2,2),(2,3),(3,1),(3,2),(3,3),(4,1),(4,2),(5,1),(5,2)]],'comparison-barrier-and-superquadratic-escape',('comparison arguments','continuation theorem'))
def global_riccati(n,k):
 answer=n*k;q=k*t**n;c=s.symbols('c',real=True);v=s.symbols('v',real=True)
 return item(r'y\prime=y^2-'+L(k*k)+r't^{'+L(2*n)+r'}+c\,t^{'+L(n-1)+r'},\quad y(0)=0,\quad t\ge0.'+T('There is a sharp real number C such that the classical solution is global exactly when c is at most C. Find C.'),answer,[(k*k*n,'differentiate the forcing coefficient without taking its square root'),(2*n*k,'differentiate the squared barrier instead of the barrier'),(-n*k,'reverse the barrier inequality'),(n/k,'invert the barrier scale'),(k,'omit the power derivative')],[T('Compare with ')+r'q(t)='+L(k)+r't^{'+L(n)+r'},\quad q\prime='+L(n*k)+r't^{'+L(n-1)+r'}.'+T('Writing ')+r'v=y-q'+T(' gives ')+r'v\prime=2qv+v^2+(c-'+L(n*k)+r')t^{'+L(n-1)+r'}.',T('At or below the stated threshold, comparison gives y at most q. On each finite time interval the forcing is bounded; a sufficiently negative constant is a lower barrier because the square term points upward. Both bounds prevent finite escape.'),T('Above the threshold, v is strictly positive after time zero and satisfies ')+r'v\prime\ge v^2.'+T('Once positive, its reciprocal decreases at least at unit speed, forcing finite-time blowup.')],[check('difference equation',((q+v)**2-k*k*t**(2*n)+c*t**(n-1))-s.diff(q,t),2*q*v+v*v+(c-n*k)*t**(n-1)),check('threshold witness residual',s.diff(q,t)-(q*q-k*k*t**(2*n)+answer*t**(n-1))),truth('positive-time forcing sign exponent',bool(n>=2 and k>0))],['Real parameter c; the polynomial vector field gives a unique maximal solution. Global means defined for every nonnegative time.'],['For c below threshold, a first-crossing comparison against q is justified by local uniqueness, or by the integrating factor for the difference equation with its nonpositive forcing. On any finite interval a negative constant below the initial state can be chosen so that its zero derivative is below the vector field there; this excludes negative escape. Above threshold, variation of constants or a first-crossing argument gives v>0 for every positive time. Its differential inequality then precludes global continuation.'],'sharp-polynomial-Riccati-global-existence-threshold')

@register('oscillator-minimum-control-energy','controllability-Gramian-minimum-energy','Represent two endpoint constraints as independent forcing moments, invert their nonorthogonal Gram matrix, and prove the resulting forcing is globally energy-minimizing.','Not a single Cauchy-Schwarz estimate: displacement and velocity constraints interact through a nonzero Gram off-diagonal.',[{'w':1,'q':str(k)} for k in [3,4,6,2,R(3,2),R(4,3),R(6,5),R(3,4),R(2,3),R(4,5)]],'Duhamel-moments-and-Gramian-projection',('variation of constants','Hilbert-space projection'))
def control(w,q):
 end=s.pi/(q*w);h=s.Matrix([s.sin(w*(end-t))/w,s.cos(w*(end-t))]);G=s.Matrix(2,2,lambda i,j:s.integrate(h[i]*h[j],(t,0,end)));e=s.Matrix([1,0]);coeff=G.inv()*e;answer=s.simplify(coeff[0])
 return item(r'x\prime\prime+'+L(w*w)+r'x=f(t),\quad x(0)=x\prime(0)=0,\quad x('+L(end)+r')=1,\quad x\prime('+L(end)+r')=0.'+T('Over all real square-integrable forcings meeting both endpoint constraints, find the minimum of ')+r'\int_0^{'+L(end)+r'}f(t)^2\,\mathrm dt.',answer,[(1/G[0,0],'ignore the terminal velocity constraint'),(1/G[1,1],'use the velocity kernel for displacement'),(G[0,0],'use the Gram matrix without inversion'),(2*answer,'double the optimal energy'),(answer/2,'halve the optimal energy')],[T('Duhamel gives the endpoint kernels ')+r'h_1(t)=\frac{\sin('+L(w)+r'('+L(end)+r'-t))}{'+L(w)+r'},\quad h_2(t)=\cos('+L(w)+r'('+L(end)+r'-t)).',T('Their Gram matrix is ')+r'G_{ij}=\int_0^{'+L(end)+r'}h_i h_j\,\mathrm dt,\qquad G='+L(G)+'.',T('Let ')+r'e=(1,0)^{\mathsf T},\quad f_*(t)=(G^{-1}e)^{\mathsf T}(h_1(t),h_2(t))^{\mathsf T}.'+T('This forcing satisfies both moments. Any other feasible forcing differs from it by a function orthogonal to both kernels, so Pythagoras proves minimality.'),r'\int_0^{'+L(end)+r'}f_*^2\,\mathrm dt=e^{\mathsf T}G^{-1}e.'],[check('two optimal endpoint moments',G*coeff,e),check('optimal quadratic energy',(coeff.T*G*coeff)[0],answer),check('exact Gram determinant',s.simplify(G.det()),(w*w*end*end-s.sin(w*end)**2)/(4*w**4))],['For square-integrable forcing, the solution has absolutely continuous velocity and satisfies the equation almost everywhere. The two endpoint kernels are linearly independent.'],['Variation of constants yields the two exact moment constraints. Linear independence of sine and cosine on a positive interval makes their Gram matrix strictly positive definite; numerical positivity is supplementary to that analytic argument. The finite integrals compute G exactly. The constructed forcing is smooth, so it lies in the admissible class and attains the global minimum.'],'forced-oscillator-two-endpoint-minimum-energy')

@register('small-loop-geometric-phase','noncommutative-flow-commutator-limit','Four flows have zero net first-order time but a nonzero commutator; identify the second-order drift and control the accumulated remainder over many loops.','Unlike a fixed switched Riccati recurrence, this is a vanishing-step limit whose effect disappears under any commutative averaging.',[{'a':a,'b':str(b)} for a,b in [(1,1),(1,2),(1,3),(2,2),(2,3),(3,3),(1,-1),(1,-2),(2,-2),(2,R(1,3))]],'flow-commutator-and-product-limit',('matrix exponentials','uniform product limits'))
def commutator(a,b):
 e=s.symbols('e');A=s.Matrix([[0,a],[0,0]]);B=s.Matrix([[0,0],[b,0]]);I=s.eye(2);M=(I+e*A)*(I+e*B)*(I-e*A)*(I-e*B);C=A*B-B*A;answer=s.exp(a*b)
 return item(r'A='+L(A)+r',\quad B='+L(B)+r'.'+T('For each positive integer N, start at ')+r'X(0)=(1,0)^{\mathsf T}.'+T('Repeat N cycles. In each cycle solve successively ')+r'X\prime=-BX,\quad X\prime=-AX,\quad X\prime=BX,\quad X\prime=AX,'+T('each for time ')+r'N^{-1/2}.'+T('Find the limit of the first coordinate after all cycles as N tends to infinity.'),answer,[(1,'cancel flows as if the generators commuted'),(s.exp(-a*b),'reverse chronological matrix order'),(s.exp(a+b),'sum the generators'),(s.exp(2*a*b),'double the commutator drift'),(s.exp(a*b/2),'halve the commutator drift')],[T('Because both generators square to zero, every short-time exponential is exactly linear. One cycle has matrix ')+r'M_h=(I+hA)(I+hB)(I-hA)(I-hB).',r'M_h=I+h^2[A,B]+O(h^3),\qquad [A,B]=AB-BA='+L(C)+'.',T('Set ')+r'h=N^{-1/2}.'+T('The accumulated cubic remainder is bounded by a constant times ')+r'Nh^3=N^{-1/2}\to0.'+T('The matrix product limit is therefore ')+r'M_h^N\to e^{[A,B]}.',T('Apply this diagonal limit to the stated initial vector.')],[check('first generator nilpotent',A*A,s.zeros(2)),check('second generator nilpotent',B*B,s.zeros(2)),check('linear cycle coefficient',M.applyfunc(lambda v:s.expand(v).coeff(e,1)),s.zeros(2)),check('quadratic cycle coefficient',M.applyfunc(lambda v:s.expand(v).coeff(e,2)),C),check('cycle determinant',M.det(),1)],['Each cycle has the specified chronological order. Big O is in any fixed matrix norm as the positive step tends to zero; I is the identity matrix.'],['The exact cycle is a degree-four matrix polynomial, so the cubic remainder has a uniform norm bound. Compare M_h^N with (I+C/N)^N using the telescoping product identity. The factors have norm at most 1+K/N for large N, hence the total difference is at most a bounded exponential factor times N times O(N^-3/2). The ordinary matrix exponential limit then gives the claim.'],'zero-mean-four-flow-commutator-effective-drift')

@register('boundary-layer-energy','singular-perturbation-boundary-layer-energy','A reduced first-order equation cannot satisfy both endpoint values; separate the boundary layer from the uniformly small bulk error before taking a scaled energy limit.','Distinct from a pointwise ODE limit: the boundary layer vanishes at every interior point but contributes the entire requested scaled integral.',[{'n':n,'b':b} for n,b in [(2,2),(3,2),(4,2),(5,2),(6,2),(2,3),(3,3),(4,-1),(5,-1),(6,3)]],'exact-polynomial-corrector-and-boundary-layer',('singular perturbation','uniform remainder estimates'))
def layer(n,b):
 e=s.symbols('epsilon',positive=True);w=sum((-e)**j*s.factorial(n)/s.factorial(n-j)*t**(n-j) for j in range(int(n)));answer=(b-1)**2/2
 return item(r'\varepsilon y_\varepsilon\prime\prime+y_\varepsilon\prime='+L(n)+r't^{'+L(n-1)+r'},\quad y_\varepsilon(0)=0,\quad y_\varepsilon(1)='+L(b)+r',\quad\varepsilon>0.'+T('Find ')+r'\lim_{\varepsilon\downarrow0}\frac1\varepsilon\int_0^1\left(y_\varepsilon(t)-t^{'+L(n)+r'}-'+L(b-1)+r'\right)^2\,\mathrm dt.',answer,[((b-1)**2,'omit the squared exponential decay rate'),((b-1)**2/4,'double the squared exponential rate'),(b*b/2,'use the right boundary value rather than the mismatch'),(R(0),'use pointwise convergence inside the scaled integral'),((b-1)**2/(2*n),'insert the polynomial degree into the layer width')],[T('A polynomial particular solution is ')+r'w_\varepsilon(t)=\sum_{j=0}^{'+L(n-1)+r'}(-\varepsilon)^j\frac{'+L(s.factorial(n))+r'}{('+L(n)+r'-j)!}t^{'+L(n)+r'-j}.'+T('It vanishes at zero and differs from the leading power uniformly by a quantity of order epsilon.'),r'y_\varepsilon=w_\varepsilon+C_\varepsilon(1-e^{-t/\varepsilon}),\quad C_\varepsilon=\frac{'+L(b)+r'-w_\varepsilon(1)}{1-e^{-1/\varepsilon}}='+L(b-1)+r'+O(\varepsilon).',T('After subtracting the displayed outer solution, the uniform bulk error is of order epsilon and the layer is ')+r'-C_\varepsilon e^{-t/\varepsilon}.',r'\frac1\varepsilon\int_0^1e^{-2t/\varepsilon}\,\mathrm dt=\frac{1-e^{-2/\varepsilon}}2\longrightarrow\frac12.'+T('The scaled bulk square and cross term tend to zero by their uniform bounds and the layer width.')],[check('exact polynomial forcing residual',e*s.diff(w,t,2)+s.diff(w,t),n*t**(n-1)),check('polynomial zero endpoint',w.subs(t,0)),check('leading polynomial limit',w.subs(e,0),t**n),check('layer integral',s.integrate(s.exp(-2*t/e),(t,0,1))/e,(1-s.exp(-2/e))/2)],['The solution is classical on the unit interval for each positive epsilon. Every asymptotic statement concerns epsilon decreasing to zero with t in the fixed unit interval.'],['The homogeneous equation has basis one and exp(-t/epsilon), so the endpoint construction is exact and unique. The finite polynomial gives a uniform O(epsilon) bound on the bulk correction. Its squared integral divided by epsilon is O(epsilon). The cross term is at most a constant times the unscaled exponential integral, also O(epsilon). Thus only the squared layer survives.'],'pointwise-invisible-boundary-layer-scaled-energy')

@register('logarithmic-relaxation-constant','nonlinear-decay-logarithmic-renormalization','Determine the constant beyond leading reciprocal decay by matching an implicit separable identity with a proved asymptotic scale.','Unlike a simple lifespan calculation, dropping the cubic term preserves the leading decay but loses both the logarithmic correction and the requested constant.',[{'a':a,'b':str(b)} for a,b in [(1,1),(1,2),(1,R(1,2)),(2,1),(2,2),(2,R(1,3)),(3,1),(3,2),(4,1),(4,R(1,2))]],'implicit-first-integral-and-asymptotic-matching',('separation','Cesaro limits'))
def relaxation(a,b):
 v=s.symbols('v',positive=True);F=1/v+a*s.log(v)-a*s.log(1+a*v);answer=1/b+a*s.log(b/(1+a*b))
 return item(r'y\prime=-y^2(1+'+L(a)+r'y),\quad y(0)='+L(b)+r'.'+T('Find ')+r'\lim_{t\to\infty}\left(\frac1{y(t)}-t-'+L(a)+r'\ln t\right).',answer,[(1/b,'drop the cubic correction'),(1/b-a*s.log(b/(1+a*b)),'reverse the logarithmic constant'),(1/b+a*s.log(b),'omit the nonlinear denominator in separation'),(1/b+a*s.log(1+a*b),'keep only the wrong endpoint logarithm'),(-answer,'reverse the elapsed-time identity'),(1/b+a*s.log(b/(1+a*b)**2),'count the nonlinear denominator logarithm twice'),(a*s.log(b/(1+a*b)),'omit the initial reciprocal endpoint'),(1/b+2*a*s.log(b/(1+a*b)),'double both logarithmic terms in the separated primitive')],[T('The solution decreases, stays positive, and tends to zero. The reciprocal ')+r'v=1/y'+T(' satisfies ')+r'v\prime=1+'+L(a)+r'/v,'+T(' so ')+r'v(t)/t\to1\quad\textnormal{and}\quad t y(t)\to1.',T('Separating the original equation gives the exact identity ')+r't=\frac1y-\frac1{'+L(b)+r'}+'+L(a)+r'\ln\!\left(\frac{y(1+'+L(a*b)+r')}{'+L(b)+r'(1+'+L(a)+r'y)}\right).',T('Rearrange the requested expression. The remaining time-dependent logarithms are multiples of ')+r'\ln(t y(t))\quad\textnormal{and}\quad\ln(1+'+L(a)+r'y(t)),'+T('which both tend to zero.')],[check('separated elapsed-time derivative',s.diff(F,v),-1/(v*v*(1+a*v))),check('reciprocal equation algebra',-(-v*v*(1+a*v))/(v*v),1+a*v)],['The positive initial value selects a positive solution for all nonnegative time. Natural logarithms are evaluated only at positive arguments.'],['The vector field is locally Lipschitz and negative for positive y. The solution cannot reach zero in finite time by uniqueness, and is bounded, hence is global. Its monotone limit must be an equilibrium, so it is zero. The reciprocal derivative tends to one; integrating and dividing by t proves v/t tends to one. The exact implicit identity then justifies the constant extraction without assuming an unjustified asymptotic series.'],'cubic-relaxation-second-order-log-constant')

@register('Bessel-zero-normalization','singular-eigenfunction-boundary-normalization','Normalize a singular-endpoint eigenfunction without integrating its square directly, using a differential identity and the root boundary condition.','Different from generic polynomial coefficient recovery: regularity at the singular endpoint removes a boundary term, while simplicity of the chosen Bessel root ensures a nonzero normalization.',[{'nu':nu,'j':j} for nu in range(5) for j in (1,2)],'Bessel-ODE-Lagrange-normalization',('Bessel equation','integration by parts'))
def bessel_norm(nu,j):
 alpha=s.Symbol('alpha',positive=True);answer=s.besselj(nu+1,alpha)**2/2
 f=s.Function('f')(t);E=t*t*s.diff(f,t)**2/2+(t*t-nu*nu)*f*f/2
 residual=s.diff(E,t).subs(s.diff(f,t,2),-s.diff(f,t)/t-(1-nu*nu/t**2)*f)
 return item(r'J_n(z)=\sum_{k=0}^{\infty}\frac{(-1)^k(z/2)^{2k+n}}{k!(k+n)!}\quad(n=0,1,2,\ldots).'+T('Let alpha be the ')+L(j)+T('-th positive zero of ')+r'J_{'+L(nu)+r'}.'+T('Evaluate ')+r'\int_0^1r\,J_{'+L(nu)+r'}(\alpha r)^2\,\mathrm dr.',answer,[(s.besselj(nu+1,alpha)**2,'omit the boundary identity factor one half'),(s.besselj(nu+1,alpha)**2/4,'apply the factor twice'),(alpha**2*s.besselj(nu+1,alpha)**2/2,'omit the scaling Jacobian'),(s.besselj(nu+1,alpha)**2/(2*alpha**2),'divide by the zero scale twice'),(s.Integer(0),'use the vanishing endpoint value instead of its derivative')],[T('The defining series solves ')+r'z^2J_n\prime\prime+zJ_n\prime+(z^2-n^2)J_n=0.'+T('Differentiate the expression ')+r'F(z)=\frac{z^2}{2}J_n\prime(z)^2+\frac{z^2-n^2}{2}J_n(z)^2.'+T('The equation gives ')+r'F\prime(z)=zJ_n(z)^2.',T('The series shows the lower endpoint contribution is zero. At the chosen root, ')+r'F(\alpha)=\frac{\alpha^2}{2}J_{'+L(nu)+r'}\prime(\alpha)^2.',T('The series also gives the recurrence ')+r'J_n\prime(z)=\frac nzJ_n(z)-J_{n+1}(z).'+T('At the root, use this relation and then substitute ')+r'z=\alpha r'+T(' in the requested integral.')],[check('formal Bessel normalization differential identity',residual,t*f*f),check('Bessel derivative recurrence',s.diff(s.besselj(nu,t),t),nu*s.besselj(nu,t)/t-s.besselj(nu+1,t))],['The Bessel functions are defined by the displayed entire power series. Alpha is a positive root, hence nonzero; the chosen positive zeros exist and are simple.'],['Termwise differentiation of the entire series gives the Bessel ODE, its derivative recurrence, and the regular-origin behavior. For order zero the derivative is O(z), and for positive integer order the function is O(z^n); these imply F(0)=0. A positive root and its derivative cannot both vanish by uniqueness for the nonsingular ODE at that point. Existence and ordering of positive Bessel zeros are standard oscillation-theory prerequisites, not asserted as machine proved. All positive zeros exceed two: on (0,2], the defining alternating series has decreasing term magnitudes; for positive integer order its first term strictly exceeds the second, and for order zero at z=2 the first two cancel but the remaining alternating tail is strictly positive. Thus alpha squared exceeds four. Together with the nonzero root derivative, this strictly orders all authored alternatives and certifies their inequivalence; symbolic non-simplification alone is not used as that proof.'],'Bessel-zero-weighted-square-boundary-normalization')

@register('Green-kernel-square-trace','Green-resolvent-parameter-identity','Construct a Green kernel from matching and jump conditions, then relate its squared norm to a parameter derivative of its diagonal trace.','Unlike direct IVP solving, the kernel depends on two positions and the parameter derivative identity replaces a difficult double integral.',[{'a':a} for a in range(1,11)],'Green-kernel-resolvent-derivative',('Green functions','parameter differentiation'))
def green_trace(a):
 aa=s.symbols('a',positive=True);u=s.symbols('u',real=True);G=s.sinh(aa*t)*s.sinh(aa*(1-u))/(aa*s.sinh(aa));diagonal=s.sinh(aa*t)*s.sinh(aa*(1-t))/(aa*s.sinh(aa));trace=s.coth(aa)/(2*aa)-1/(2*aa*aa)
 answer=(s.coth(a)/(4*a**3)+1/(4*a*a*s.sinh(a)**2)-1/(2*a**4))
 return item(T('For each s in the open unit interval, let G(t,s) be continuous in t, vanish at t=0 and t=1, satisfy ')+r'-G_{tt}+'+L(a*a)+r'G=0\quad(t\ne s),\quad G_t(s^+,s)-G_t(s^-,s)=-1.'+T('Evaluate ')+r'\int_0^1\int_0^1G(t,s)^2\,\mathrm dt\,\mathrm ds.',answer,[(s.coth(a)/(2*a**3)+1/(2*a*a*s.sinh(a)**2)-1/a**4,'omit the derivative factor two'),(-answer,'reverse the inverse-operator derivative sign'),(s.coth(a)/(4*a**3)-1/(2*a**4),'omit the derivative of hyperbolic cotangent'),(s.coth(a)/(4*a**3)+1/(4*a*a*s.sinh(a)**2),'omit the endpoint normalization term'),(s.coth(a)/(4*a**3)-1/(4*a*a*s.sinh(a)**2)-1/(2*a**4),'reverse the derivative sign of hyperbolic cotangent')],[T('Matching homogeneous solutions and the unit derivative jump gives the symmetric kernel ')+r'G_a(t,s)=\frac{\sinh(a\min\{t,s\})\sinh(a(1-\max\{t,s\}))}{a\sinh a}.',T('Its diagonal integral is ')+r'T(a)=\int_0^1G_a(t,t)\,\mathrm dt=\frac{\coth a}{2a}-\frac1{2a^2}.',T('Differentiate the defining operator equation in a. The same zero-boundary Green inverse gives ')+r'\partial_aG_a(t,s)=-2a\int_0^1G_a(t,r)G_a(r,s)\,\mathrm dr.',T('Set s=t, integrate, and use symmetry: the requested squared norm is ')+r'-\frac{T\prime(a)}{2a}'+T(' evaluated at ')+L(a)+'.'],[check('left Green branch homogeneous residual',-s.diff(G,t,2)+aa*aa*G),check('Green derivative jump',(-s.sinh(aa*u)*s.cosh(aa*(1-u))-s.cosh(aa*u)*s.sinh(aa*(1-u)))/s.sinh(aa),-1),check('diagonal trace integral',s.integrate(diagonal,(t,0,1)),trace),check('squared trace parameter derivative',(-s.diff(trace,aa)/(2*aa)).subs(aa,a),answer)],['Real a>0 in the derivation; s is the second position coordinate, not a parameter. coth means cosh divided by sinh.'],['The homogeneous Dirichlet problem has only the zero solution, by integrating the positive energy, so the matched Green kernel is unique. Its compact-domain hyperbolic formula is smoothly parameter-dependent for positive a. Differentiating the inverse equation produces a source -2aG with zero boundaries; applying the same Green inverse proves the displayed resolvent identity. All compact integrals are continuous, so differentiation and integration commute.'],'Dirichlet-Green-kernel-Hilbert-Schmidt-trace')

@register('inverse-period-potential','inverse-period-Abel-potential','Recover the turning-point coordinate from an entire energy-dependent period function; invert the Abel convolution and use evenness to rule out shear ambiguity.','The direct period and isochronous-shear constructions start from a potential. Here the period data are given, and the unknown potential must be recovered through an integral inversion.',[{'a':a,'e':e} for a,e in [(1,1),(1,2),(1,3),(2,1),(2,2),(2,3),(3,1),(3,2),(4,1),(4,2)]],'period-energy-Abel-inversion',('energy quadrature','nonnegative convolution interchange'))
def inverse_period(a,e):
 answer=s.sqrt(2*e)*(1+R(2,3)*a*e);u=s.symbols('u',positive=True)
 return item(T('A particle satisfies ')+r'x\prime\prime+V\prime(x)=0.'+T('The potential is even, smooth, has V(0)=0, and is strictly increasing for positive x. Every positive energy has a periodic orbit with period ')+r'P(E)=2\pi(1+'+L(a)+r'E).'+T('Find the positive turning point at energy ')+L(e)+'.',answer,[(s.sqrt(2*e)*(1+a*e),'identify period with the coordinate derivative without Abel inversion'),(s.sqrt(2*e)*(1+a*e/3),'halve the linear-period contribution'),(s.sqrt(2*e)*(1+R(4,3)*a*e),'double the linear-period contribution'),(s.sqrt(2*e),'ignore the energy dependence of the period'),(s.sqrt(2*e)*(1+R(2,3)*a*e)**2,'square the recovered coordinate')],[T('Let X(E)>0 be the inverse of the increasing positive branch of V. Energy conservation gives ')+r'P(E)=2\sqrt2\int_0^E\frac{X\prime(v)}{\sqrt{E-v}}\,\mathrm dv.',T('Integrate once more against the inverse-square-root kernel. Tonelli and the beta integral ')+r'\int_v^E\frac{\mathrm du}{\sqrt{(u-v)(E-u)}}=\pi'+T(' give ')+r'X(E)=\frac1{2\sqrt2\pi}\int_0^E\frac{P(u)}{\sqrt{E-u}}\,\mathrm du.',T('Insert the stated period and integrate its constant and linear terms: ')+r'X(E)=\sqrt{2E}\left(1+\frac{'+L(2*a)+r'}3E\right).'+T('Evaluate at the requested energy.')],[check('independent Abel inversion integral',s.integrate(2*s.pi*(1+a*u)/s.sqrt(e-u),(u,0,e))/(2*s.sqrt(2)*s.pi),answer),check('unit beta convolution',s.integrate(1/s.sqrt(u*(1-u)),(u,0,1)),s.pi),truth('positive monotone reconstructed branch',bool(a>0 and e>0))],['Energy is kinetic energy plus V. The turning point is the positive inverse branch. The hypotheses include periodic orbits at every positive energy.'],['Evenness makes the two sides of the orbit equal, fixing the quarter-period factor and excluding arbitrary even shears of an inverse coordinate. Positivity permits Tonelli. The inverse branch may be handled by monotone Stieltjes integration if its derivative has an endpoint singularity; the period data reconstruct a smooth strictly increasing X on positive energies. The recovered expression tends to zero at zero and is onto the positive half-line, so it defines the required positive potential branch.'],'energy-period-data-to-turning-coordinate')

@register('bistable-front-speed','bistable-heteroclinic-speed-selection','Two asymptotic equilibria select a unique wave speed; construct a monotone front and compare phase-plane graphs to exclude all other speeds.','Distinct from the conservative homoclinic mass: friction is unknown and the two unequal end states impose a speed-selection condition.',[{'k':k,'a':str(a)} for k,a in [(1,R(1,3)),(1,R(2,3)),(1,R(1,4)),(1,R(3,4)),(2,R(1,3)),(2,R(2,3)),(2,R(1,5)),(2,R(4,5)),(3,R(2,5)),(3,R(3,5))]],'heteroclinic-profile-and-phase-plane-comparison',('phase-plane graphs','hyperbolic equilibrium asymptotics'))
def front(k,a):
 f=1/(1+s.exp(k*t));answer=k*(1-2*a);U=s.symbols('U',real=True);p=k*U*(1-U)
 return item(r'y\prime\prime+c y\prime+'+L(2*k*k)+r'y(1-y)(y-'+L(a)+r')=0.'+T('Find the unique real c for which there is a strictly decreasing classical solution with ')+r'\lim_{t\to-\infty}(y,y\prime)=(1,0),\quad\lim_{t\to\infty}(y,y\prime)=(0,0).',answer,[(-answer,'reverse the front direction'),(2*k*(1-2*a),'double the damping normalization'),(k*(1-a),'omit one equilibrium contribution'),(k*a,'use the unstable equilibrium as the speed fraction'),(k*k*(1-2*a),'use the reaction scale rather than its square root'),(answer/2,'halve the wave speed after matching'),(k*(1-2*a)/s.sqrt(2),'omit the factor two in the reaction scale'),(-2*answer,'reverse the wave and double the matching coefficient')],[T('A candidate monotone profile is ')+r'y(t)=\frac1{1+e^{'+L(k)+r't}},\quad y\prime=-'+L(k)+r'y(1-y).'+T('Substitution gives the displayed speed.'),T('To see uniqueness, write any decreasing front as ')+r'p(u)=-y\prime>0,\quad u=y\in(0,1).'+T('Then ')+r'p\frac{\mathrm dp}{\mathrm du}=cp-'+L(2*k*k)+r'u(1-u)(u-'+L(a)+r').',T('The positive slope of p near zero increases strictly with c, whereas the positive coefficient of p near one decreases strictly with c. Thus if a larger speed had a second front, its p-graph would begin above the first and end below it.'),T('At any intersection of two positive phase graphs, their derivative difference equals their speed difference. A larger-speed graph therefore cannot cross from above to below. This contradiction proves uniqueness.')],[check('logistic front original ODE',s.diff(f,t,2)+answer*s.diff(f,t)+2*k*k*f*(1-f)*(f-a)),check('phase-plane profile equation',p*s.diff(p,U),answer*p-2*k*k*U*(1-U)*(U-a)),check('profile positive velocity magnitude',-s.diff(f,t),k*f*(1-f)),truth('bistable interior equilibrium',bool(0<a<1))],['The front is strictly decreasing and joins one to zero; translating time does not alter its speed. The two limiting derivatives are explicitly zero.'],['The verified logistic profile has both limits and gives existence. At the hyperbolic equilibria, standard stable-manifold asymptotics give p(u)/u tending to (c+sqrt(c squared+8k squared*a))/2 and p(u)/(1-u) tending to (-c+sqrt(c squared+8k squared*(1-a)))/2. These are respectively strictly increasing and decreasing in c. The crossing argument then proves uniqueness. The hyperbolic-endpoint asymptotic theorem is an explicit analytic prerequisite, not a symbolic-check claim.'],'bistable-front-unique-speed-from-phase-comparison')

@register('Robin-Lyapunov-infimum','sharp-L1-Sturm-potential-threshold','The smallest total nonnegative potential supporting a boundary eigenfunction is the reciprocal of a Green-kernel maximum; the maximizing point moves from a boundary to the interior as the Robin parameter changes.','This is an infimum over potentials, not a fixed-potential spectrum. Sharpness requires concentrating smooth forcing near the correct Green maximum, and the infimum is not attained.',[{'ell':str(ell),'h':str(h)} for ell,h in [(1,0),(1,R(1,2)),(1,1),(1,2),(1,3),(2,0),(2,R(1,4)),(2,R(1,2)),(2,1),(2,2)]],'positive-Green-bound-and-concentrating-witness',('Sturm boundary problems','Green kernels','sharp infima'))
def lyapunov(ell,h):
 location=ell if h*ell<=1 else (1+h*ell)/(2*h);Gdiag=t*(1+h*(ell-t))/(1+h*ell);maximum=s.simplify(Gdiag.subs(t,location));answer=1/maximum
 return item(T('Let q range over continuous nonnegative functions on ')+r'[0,'+L(ell)+r']'+T('for which ')+r'y\prime\prime+q(t)y=0,\quad y(0)=0,\quad y\prime('+L(ell)+r')+'+L(h)+r'y('+L(ell)+r')=0'+T('has a nonzero real solution. Find ')+r'\inf_q\int_0^{'+L(ell)+r'}q(t)\,\mathrm dt.',answer,[(4/ell,'use the two-Dirichlet-endpoint constant'),(1/ell,'use the pure Neumann-endpoint constant'),(2*answer,'double the Green normalization'),(answer/2,'halve the Green normalization'),(maximum,'use the Green maximum rather than its reciprocal'),((1+h*ell)**2/ell,'square the Robin factor'),(4*answer,'count the maximizing kernel branch four times'),(answer/4,'divide the potential bound by four again')],[T('For the operator minus the second derivative with these boundaries, the positive Green kernel is ')+r'G(t,s)=\frac{\min\{t,s\}\,[1+'+L(h)+r'('+L(ell)+r'-\max\{t,s\})]}{'+L(1+h*ell)+r'}.',T('Every nonzero solution satisfies the Green equation. Taking its maximum absolute value gives ')+r'1\le\left(\max_{t,s}G(t,s)\right)\int_0^{'+L(ell)+r'}q(s)\,\mathrm ds.',T('For each s, the maximum in t occurs on the diagonal. Maximize ')+r'g(s)=\frac{s[1+'+L(h)+r'('+L(ell)+r'-s)]}{'+L(1+h*ell)+r'}.'+T('Its maximizing location is ')+L(location)+T(' and its maximum is ')+L(maximum)+'.',T('For sharpness, take smooth unit-mass nonnegative sources concentrated near this location. Let y be their Green potential and set q equal to source divided by y. Then the boundary problem holds and the potential integral tends to the reciprocal maximum.')],[check('Green diagonal at maximizer',Gdiag.subs(t,location),maximum),truth('maximizer in closed interval',bool(0<location<=ell)),check('concave Green diagonal curvature',s.diff(Gdiag,t,2),-2*h/(1+h*ell)),truth('Robin endpoint nonnegative',bool(h>=0 and ell>0))],['The infimum is over continuous nonnegative potentials, not over a single supplied q. A nonzero eigenfunction is required. The endpoint parameter h is nonnegative.'],['The Green formula follows from affine branches with a negative unit derivative jump and the displayed boundary conditions. It is nonnegative, and G(t,s)<=G(s,s). Its diagonal is concave; the unconstrained vertex lies inside exactly when h*ell>=1. For sharpness choose smooth probability densities supported in a small interior neighborhood approaching the maximizing point, including from the left if the maximum is at the endpoint. Their Green potentials are positive on the supports and satisfy the boundaries. Defining q as density divided by potential on the support and zero outside is continuous when the density vanishes smoothly at its support endpoints. Uniform convergence of the Green kernel on the shrinking support makes the total q tend to 1/Gmax. Strict inequality for every continuous nonzero potential shows no minimum is attained.'],'sharp-Robin-Sturm-total-potential-infimum')

@register('pantograph-entire-growth','pantograph-discrete-saddle-growth','A dilation differential equation determines a strongly damped coefficient sequence; estimate the maximum term and the whole series to obtain a logarithmic growth order.','A coefficient recurrence alone is insufficient: the requested growth constant comes from optimizing an index that tends to infinity and controlling factorial and Gaussian-tail errors.',[{'b':b} for b in range(2,12)],'analytic-coefficient-recurrence-and-discrete-saddle',('entire power series','maximum-term estimates'))
def pantograph(b):
 q=1/b;answer=1/(2*s.log(b));n=s.symbols('n',integer=True,nonnegative=True);coeff=q**(n*(n-1)/2)/s.factorial(n)
 return item(T('Let F be the entire solution of ')+r'F\prime(z)=F(z/'+L(b)+r'),\quad F(0)=1.'+T('For positive real r, find ')+r'\lim_{r\to\infty}\frac{\ln F(r)}{(\ln r)^2}.',answer,[(1/s.log(b),'omit the quadratic coefficient factor one half'),(1/(4*s.log(b)),'double the quadratic decay in the coefficients'),(s.log(b)/2,'invert the saddle scale'),(R(0),'assume factorial decay dominates the dilation effect at the selected index'),(1/(2*b),'replace the logarithm of the dilation by the dilation')],[T('Coefficient comparison gives ')+r'F(z)=\sum_{n=0}^{\infty}\frac{'+L(q)+r'^{n(n-1)/2}}{n!}z^n.'+T('The ratio test proves entire convergence and all coefficients are positive.'),T('Write ')+r'L=\ln r,\quad c=\ln '+L(b)+r'>0.'+T('Ignoring the factorial only for an upper bound, complete the square in ')+r'nL-\frac c2n(n-1).'+T('The resulting discrete Gaussian sum is bounded by a constant depending only on c, times ')+r'\exp\left(\frac{(L+c/2)^2}{2c}\right).',T('For the lower bound retain the single term with ')+r'n=\lfloor L/c\rfloor.'+T('Its logarithm is ')+r'\frac{L^2}{2c}+O(L\ln L),'+T('because ')+r'0\le\ln(n!)\le n\ln n.'+T('Divide both bounds by the square of L.')],[check('coefficient dilation recurrence',s.simplify((n+1)*coeff.subs(n,n+1)/coeff),q**n),truth('strict contraction dilation',bool(0<q<1)),check('quadratic saddle leading coefficient',s.diff(z*t-s.log(b)*z*(z-1)/2,z,2),-s.log(b))],['The complex variable z defines the entire function; the requested limit uses positive real r, where F(r)>0. The auxiliary L in the solution is ln r, not an interval length.'],['The coefficient ratio is |z|q^n/(n+1), tending to zero for every fixed z, proving existence and uniqueness among entire solutions. For the upper estimate, the sum of exp(-c(n-center)^2/2) over integer n is uniformly bounded over all centers by a constant plus its Gaussian integral. The lower index differs from L/c by less than one, so its quadratic exponent differs from L squared/(2c) by O(L); the factorial bound costs only O(L ln L). These two analytic estimates prove the limit.'],'pantograph-entire-function-logarithmic-order')

@register('minimum-peak-acceleration','bang-bang-endpoint-control','Two terminal constraints force a nontrivial switch in the extremal bounded acceleration; use a rearrangement inequality for a decreasing time kernel and solve the sharp feasibility equation.','Unlike the quadratic-energy Gramian problem, a supremum norm creates a saturated two-level control and an unknown switching time.',[{'Tend':str(tt),'V':v,'D':str(d)} for tt,v,d in [(1,0,1),(1,1,1),(1,-1,1),(2,1,2),(2,-1,1),(2,0,3),(1,2,2),(1,-2,1),(R(1,2),1,1),(R(3,2),-1,2)]],'bang-bang-rearrangement-and-endpoint-feasibility',('integral control constraints','rearrangement inequalities'))
def peak(Tend,V,D):
 delta=2*D-V*Tend;answer=(delta+s.sqrt(delta*delta+Tend*Tend*V*V))/(Tend*Tend);switch=(Tend+V/answer)/2
 displacement=answer*(Tend*switch-switch*switch/2)-answer*(Tend-switch)**2/2
 return item(r'x\prime\prime=u(t),\quad x(0)=x\prime(0)=0,\quad x('+L(Tend)+r')='+L(D)+r',\quad x\prime('+L(Tend)+r')='+L(V)+r'.'+T('Among real measurable essentially bounded accelerations, find the smallest possible essential supremum of the absolute acceleration.'),answer,[(4*D/(Tend*Tend),'ignore the terminal velocity'),(abs(V)/Tend,'use only the terminal velocity bound'),(2*D/(Tend*Tend),'assume constant acceleration despite the velocity constraint'),(2*answer,'double the sharp peak'),(answer/2,'halve the sharp peak')],[T('For a proposed peak M, the endpoint constraints are ')+r'\int_0^{'+L(Tend)+r'}u\,\mathrm dt='+L(V)+r',\quad\int_0^{'+L(Tend)+r'}('+L(Tend)+r'-t)u(t)\,\mathrm dt='+L(D)+r'.',T('With the first integral fixed, the second is largest when u equals M as early as possible and minus M afterward. The switch is ')+r'\tau=\frac12\left('+L(Tend)+r'+\frac{'+L(V)+r'}M\right).',T('This two-level control has maximal displacement ')+r'\frac{M('+L(Tend)+r')^2}{4}+\frac{'+L(V*Tend)+r'}2-\frac{'+L(V*V)+r'}{4M}.',T('The requested displacement exceeds the midpoint value. Equating it to this upper bound and choosing the positive quadratic root gives M. The corresponding switch lies inside the time interval and realizes both endpoints.')],[check('switch velocity constraint',answer*(2*switch-Tend),V),check('switch displacement constraint',s.simplify(displacement),D),check('positive-root feasibility equation',s.simplify(Tend*Tend*answer**2+(2*V*Tend-4*D)*answer-V*V)),truth('upper displacement regime',bool(delta>0))],['The equation holds almost everywhere; position has absolutely continuous velocity. The essential supremum ignores changes on sets of measure zero.'],['For fixed M and the mean constraint, compare any admissible control with the two-level control at tau. The integral of their difference is zero, and (Tend-t)-(Tend-tau) has the same sign as the saturated control difference, so the weighted displacement difference is nonnegative. This proves the extremal bound without assuming a control theorem. The positive quadratic root is at least |V|/Tend and is strictly larger in the stated regime, so the switch is feasible. The explicit saturated control attains the minimum.'],'sharp-peak-acceleration-two-endpoint-bang-bang')
